using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Enums;namespace Namaa.Application.Quotations.Commands.AddQuotationItem;public sealed class AddQuotationItemCommandHandler(IQuotationRepository repository,IServiceRepository services,IApplicationDbContext db):IRequestHandler<AddQuotationItemCommand,Result<QuotationItemDto>>{public async Task<Result<QuotationItemDto>>Handle(AddQuotationItemCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.QuotationId,cancellationToken);if(e is null)return Result.Failure<QuotationItemDto>(QuotationErrors.NotFound);if(e.Status!=QuotationStatus.Draft)return Result.Failure<QuotationItemDto>(QuotationErrors.NotDraft);if(request.ServiceId.HasValue&&await services.FindByIdAsync(request.ServiceId.Value,cancellationToken)is null)return Result.Failure<QuotationItemDto>(QuotationErrors.ServiceNotFound);var item=e.AddItem(request.Description,request.Quantity,request.UnitPrice,request.DiscountAmount,request.TaxAmount,request.ServiceId);await db.SaveChangesAsync(cancellationToken);return Result.Success(QuotationItemDto.FromEntity(item));}}

